scene.add(new THREE.HemisphereLight(0x8db5c4,0x15151c,1.25));const keyLight=new THREE.DirectionalLight(0x9bd5de,2.1);keyLight.position.set(-7,13,5);keyLight.castShadow=true;keyLight.shadow.mapSize.set(1024,1024);keyLight.shadow.camera.left=-24;keyLight.shadow.camera.right=24;keyLight.shadow.camera.top=24;keyLight.shadow.camera.bottom=-24;scene.add(keyLight);
const mats={floor:new THREE.MeshStandardMaterial({color:0x202a30,roughness:.8,metalness:.48}),wall:new THREE.MeshStandardMaterial({color:0x28343a,roughness:.72,metalness:.58}),dark:new THREE.MeshStandardMaterial({color:0x10191e,roughness:.7,metalness:.62}),trim:new THREE.MeshStandardMaterial({color:0x42545a,roughness:.38,metalness:.8}),cyan:new THREE.MeshStandardMaterial({color:0x62e4e6,emissive:0x22bfc9,emissiveIntensity:2.2,roughness:.25}),amber:new THREE.MeshStandardMaterial({color:0xffae4e,emissive:0xb75112,emissiveIntensity:1.4}),cover:new THREE.MeshStandardMaterial({color:0x344047,roughness:.8,metalness:.4})};
const solids=[],decor=[],enemies=[],shots=[],effects=[];let gameMode='survival',running=false,paused=false,score=0,wave=0,kills=0,playerHealth=100,armor=50,grounded=true,velocityY=0,lastTime=0,spawnTimer=0,mouseDown=false,fireClock=0,reloadTimer=0,hitTimer=0,damageTimer=0,toastTimer=0,elapsed=0,practiceTimer=0,accuracyShots=0,accuracyHits=0;
