// Glowing ceiling strips and warning beacons.
for(const [x,z] of [[-13,-13],[13,-13],[-13,13],[13,13],[0,-17],[0,17]]){box(scene,[x,4.85,z],[3.3,.12,.24],mats.cyan,false);light([x,4.1,z],0x39cbd3,11,9)}
// Overhead catwalks around the central chamber, supported by metal legs.
