// Ramps make the raised catwalks accessible.
for(const z of [-7.3,7.3]){const ramp=box(scene,[-9,1.68,z],[5,.32,2.1],mats.cover);ramp.rotation.z=z<0?-.3:.3;box(scene,[-11.4,1.8,z],[.2,1.8,2.2],mats.trim,false)}
