const reactor=new THREE.Group();reactor.position.set(0,0,0);scene.add(reactor);const core=new THREE.Mesh(new THREE.CylinderGeometry(1.05,1.3,2.9,8),mats.dark);core.position.y=1.45;core.castShadow=true;reactor.add(core);const coreGlow=new THREE.Mesh(new THREE.CylinderGeometry(.35,.5,2.55,8),mats.cyan);coreGlow.position.y=1.46;reactor.add(coreGlow);for(let i=0;i<4;i++){const a=i*Math.PI/2;box(reactor,[Math.cos(a)*1.1,1.5,Math.sin(a)*1.1],[.22,3,.22],mats.trim,false)}light([0,2,0],0x33d8df,18,8);
// Floor lane markings, drainage strips, bolts and scattered luminous terminals.
for(let x=-18;x<=18;x+=3){box(scene,[x,.012,0],[.035,.02,36],x%6===0?mats.trim:mats.dark,false)}
for(let z=-18;z<=18;z+=3)box(scene,[0,.014,z],[36,.018,.035],mats.dark,false);
for(let x=-18;x<=18;x+=6)for(let z=-18;z<=18;z+=6){const bolt=new THREE.Mesh(new THREE.CylinderGeometry(.055,.055,.025,8),mats.trim);bolt.position.set(x,.04,z);scene.add(bolt)}
// Wall vents and small control consoles give the room a lived-in industrial scale.
for(const side of [-1,1])for(let z=-15;z<=15;z+=10){box(scene,[side*20.52,2.8,z],[.12,1.2,3.2],mats.dark,false);for(let j=0;j<5;j++)box(scene,[side*20.43,2.8,z-1+j*.48],[.08,.055,2.5],mats.trim,false);box(scene,[side*19.7,.65,z],[.8,1.3,1.1],mats.dark);box(scene,[side*19.27,1,z],[.04,.45,.62],mats.cyan,false)}

